/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Float, Mul, Pow, Relational, Sym, SymFunction, add, combsimp, exp, fn, gammasimp, mul, pi, piecewise, pow, powsimp, rational, simplify, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.simplify.combsimp", () => {
  it("combsimp(factorial(n)/factorial(n - 3))", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(combsimp(mul(pow(fn('factorial', [add(-3, n)]), -1), fn('factorial', [n]))))).toBe('n*(n - 2)*(n - 1)');
  });
  it("combsimp(binomial(n+1, k+1)/binomial(n, k))", () => {
    const n = new Sym('n', { integer: true });
    const k = new Sym('k', { integer: true });
    expect(sympyStr(combsimp(mul(pow(fn('binomial', [n, k]), -1), fn('binomial', [add(1, n), add(1, k)]))))).toBe('(n + 1)/(k + 1)');
  });
});

describe("doctests of sympy.simplify.gammasimp", () => {
  it("gammasimp(gamma(x)/gamma(x - 3))", () => {
    const x = new Sym('x');
    expect(sympyStr(gammasimp(mul(pow(fn('gamma', [add(-3, x)]), -1), fn('gamma', [x]))))).toBe('(x - 3)*(x - 2)*(x - 1)');
  });
  it("gammasimp(gamma(n + 3))", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(gammasimp(fn('gamma', [add(3, n)])))).toBe('gamma(n + 3)');
  });
});

